-- Generated by Loom
-- Generator: hub
-- Hash function: sha256
{{ config(materialized='incremental', incremental_strategy='append') }}
SELECT DISTINCT
    LOWER(sha256(UPPER(TRIM(CAST(customer_id AS VARCHAR))))) AS customer_hk,
    UPPER(TRIM(CAST(customer_id AS VARCHAR))) AS customer_id,
    'orders_system' AS __record_source,
    localtimestamp AS __loaded_at
FROM {{ ref('stg_customers') }}
WHERE customer_id IS NOT NULL
{% if is_incremental() %}
  AND LOWER(sha256(UPPER(TRIM(CAST(customer_id AS VARCHAR))))) NOT IN (
    SELECT target.customer_hk FROM {{ this }} AS target
  )
{% endif %}
